#[test]
fn logical_humanoid_motion_identity_excludes_target_model() {
    let motion = AssetId::generate();
    let first_target = AssetId::generate();
    let second_target = AssetId::generate();
    let logical = imported_logical_humanoid_motion_sub_asset_id(&motion, 0);

    assert_eq!(
        expected_imported_sub_asset_id(
            &motion,
            &ImportedSubAsset {
                id: logical.as_str().to_owned(),
                kind: ImportedSubAssetKind::HumanoidMotion,
                name: "walk".into(),
                index: 0,
                target_model_source: Some(first_target.as_str().to_owned()),
            },
        )
        .expect("first Humanoid id must derive"),
        logical
    );
    assert_eq!(
        expected_imported_sub_asset_id(
            &motion,
            &ImportedSubAsset {
                id: logical.as_str().to_owned(),
                kind: ImportedSubAssetKind::HumanoidMotion,
                name: "walk".into(),
                index: 0,
                target_model_source: Some(second_target.as_str().to_owned()),
            },
        )
        .expect("second Humanoid id must derive"),
        logical
    );
}

